  if (kind === 'carry') return `<th colspan="${span}">${U()} · metres · time</th>`;
  if (kind === 'capcarry') return `<th colspan="${span}">${U()} · metres in ${esc(capLabel(e.cap))}</th>`;
  if (kind === 'race') return `<th colspan="${span}">top ${U()} · implements · metres · time</th>`;
  if (kind === 'cap') return `<th class="c-kg">${U()}</th>${pl}<th class="c-reps" colspan="2">Reps in ${esc(capLabel(e.cap))}</th>`;
